-- Брендбук: описание компании и правила написания имени.
--
-- Тексты собраны только из проверенных записей базы знаний. Заявленные на
-- сайте цифры («700+ проектов», «87% повторных») сюда намеренно не взяты:
-- они помечены как требующие проверки и до подтверждения в фирменные
-- материалы идти не должны.

insert into public.brand (id, title, kind, sort, data) values

('about', 'О компании', 'text', 4, jsonb_build_object('body',
  E'ADERVIS Digital — студия визуальных решений для бизнеса. Работаем с 2018 года, база в Перми, проекты по России.\n\nДелаем видео, дизайн, фото, графику, анимацию и ИИ-контент. Главное отличие — всё под ключ и по одному договору: заказчику не нужно собирать подрядчиков и сводить их между собой.\n\n— Компанией руководят два человека, они же ведут проекты лично\n— На крупные работы привлекаются профильные специалисты под задачу\n— Кроме студии развиваем два продукта: Adervis CRM для смет и КП и Adervis Stock для доступа к ассетам Envato')),

('directions', 'Направления', 'text', 6, jsonb_build_object('body',
  E'Четыре направления студии. У каждого свой цвет — он работает как навигация, а не как украшение.\n\n— Видео (красный): рекламные ролики по сценарию и раскадровке, отчётные ролики с мероприятий, монтаж для выставочных экранов\n— Дизайн (фиолетовый): логотипы, фирменный стиль, полиграфия, сайты\n— Фото (золото): съёмка мероприятий, рекламная и предметная съёмка\n— ИИ и графика (зелёный): заставки для экранов, анимация, ИИ-контент')),

('naming', 'Как пишется имя', 'text', 8, jsonb_build_object('body',
  E'Одна ошибка в написании названия стоит дороже, чем кажется: она сразу видна в документах и на макетах.\n\n— Компания пишется заглавными: ADERVIS. Полное имя — ADERVIS Digital\n— Продукты пишутся с заглавной, без капса: Adervis CRM, Adervis Stock\n— Нельзя: Адервис, Adervis Digital капсом целиком, ADERVIS CRM, adervis crm\n— Адреса: adervis.ru — студия, app.adervis.ru — CRM, stock.adervis.ru — Stock'))

on conflict (id) do nothing;

-- Та же суть — записью базы знаний, чтобы ею могли пользоваться тексты и ИИ.
